from hypothesis import strategies as st


@st.composite
def gen(draw):
    n = draw(st.integers(1, 6))
    k = draw(st.integers(1, min(n, 10)))
    val = st.one_of(st.integers(1, 50), st.sampled_from([1, 2, 49, 50]))
    pairs = draw(st.lists(st.tuples(val, val), min_size=n, max_size=n))
    lines = [f"{n} {k}"] + [f"{a} {b}" for a, b in pairs]
    return "\n".join(lines) + "\n"


