    t = inp.split()
    if len(t) < 2:
        return False
    n, k = int(t[0]), int(t[1])
    if not (1 <= n <= 2 * 10**5):
        return False
    if not (1 <= k <= min(n, 10)):
        return False
    if len(t) != 2 + 2 * n:
        return False
    vals = [int(x) for x in t[2:]]
    return all(1 <= v <= 50 for v in vals)


