    t = inp.split()
    n, k = int(t[0]), int(t[1])
    A = []
    B = []
    for i in range(n):
        A.append(int(t[2 + 2 * i]))
        B.append(int(t[3 + 2 * i]))
    best = None
    # Try every ordered selection of K distinct indices p_1..p_K.
